  }
  if (id !== null) return enter(p, id, why);
  if (blockedOnSupplies(p.id)) return enter(p, "supplies", why);
  if (KNOBS.idle === "stay" && D.jobs[p.step.id] && !p.layoutShort()) { noteGuide(p, "stay", null, "keeping " + p.step.id + " standing", guideWait[p.id]); return; } // keep it standing, no re-placing
  enter(p, "hub", why);
}

/** A target of a still-needed product is growing and at least KNOBS.drain grown: worth finishing. */
function maturing(p, job) {
  if (KNOBS.drain >= 1) return false;
  return p.targets.some((t) => t.filled && t.plant && !t.plant.fullyGrown && job.produces.includes(t.mutation) && needed(t.mutation)
    && t.plant.stage >= KNOBS.drain * Math.max(1, t.plant.growthStages));
}

// ---- special farms ----

// Guaranteed fragment yield of an Aloe harvest at this stage (the fractional extra is a bonus).
const ALOE_FRAGMENTS = [0,0,0,0,1,2,3,4,6,9,13,20,28,41,60,86,125,182,263,382,554,803,1164,1688,2448,3549,5146,7462];
/**
 * Guaranteed part of the greenhouse yield sum that scales a mutation's OWN item count. Current
 * game: none (the update "Fixed Plant Yield bonuses incorrectly applying to mutation items"), so 1.
 * With the simulator's legacyMutationYield setting the old sum applies (upgrade, Flora, effects).
 */
function yieldSum(plant) {
  if (!config.legacyMutationYield) return 1;
  let sum = 1 + stats.plantYieldUpgrade + 0.025 * Math.min(10, (stats.floraShard ?? 0));
  const fx = plant.effects;
  if (fx.includes("improved_harvest_boost")) sum += 0.3;
  else if (fx.includes("harvest_boost")) sum += 0.2;
  if (fx.includes("harvest_loss")) sum -= 0.2;
  return sum;
}
function aloeFloor(plant) {
  return Math.floor(ALOE_FRAGMENTS[Math.min(27, plant.stage)] * yieldSum(plant) + 0.000000001);
}

function pickTargets(p) {
  const step = p.step.id;
  if (step === "jelly") {
    const beans = p.spawns("magic_jellybean");
    // Items a Jellybean gives now: 1 at stage 12, +1 every 12 stages, scaled by yield.
    const items = (j) => j.stage < 12 ? 0 : Math.floor((1 + Math.floor((j.stage - 12) / 12)) * yieldSum(j) + 0.000000001);
    const stillNeeded = net("magic_jellybean");
    const finishNow = KNOBS.jellyFinish && stillNeeded > 0 && beans.sum((j) => items(j)) >= stillNeeded;
    for (const j of beans) {
      if ((j.stage >= KNOBS.jellyStage || (finishNow && j.stage >= 12)) && j.break()) picks.jellybeans += 1;
    }
  } else if (step === "aloe") {
    const missing = Math.max(0, (D.legendaries.all_in_aloe - inv("all_in_aloe")) * 9 - inv("all_in_aloe_fragment"));
    for (const a of p.spawns("all_in_aloe")) {
      if (missing > 0 && (a.stage >= KNOBS.aloeStage || aloeFloor(a) >= missing) && a.break()) picks.aloe += 1;
    }
  }
}

/** Shellfruit: once the placed Blastberries are primed, break only them; every Turtlellini is hit twice. */
function popShellfruit(p) {
  const berries = p.all("blastberry");
  if (berries.length && !berries.every((b) => b.primed)) return false;
  p.breakAll("blastberry");
  p.harvestAll("shellfruit");
  picks.shellfruit += 1;
  return true;
}

// ---- the session ----

function finish() {
  noteGuide(plot, "done", null, "goal complete");
  if (plot.step.id !== "done") plot.goto("done");
  plot.hold(false);
  plot.runPhase("stepChange"); // the Done step's own exit marks the flow finished
}

function tend(p) {
  const id = p.step.id;
  guideWait[p.id] = [];
  if (id === "done") { noteGuide(p, "done", null, "goal complete"); return; }
  pickTargets(p);
  if (id === "hub" || id === "supplies") return next(p, "idle");
  if (id === "shellfruit" || id === "shellfruit-cheese") {
    if (popShellfruit(p)) { next(p, "shellfruit popped"); return; }
    noteGuide(p, "stay", null, "waiting for the Blastberries to prime");
    return;
  }
  const job = D.jobs[id];
  if (job) {
    const held = job.produces.filter((p) => needed(p) && !(inv(p) >= high(p) && !stopsOnNeed(id)));
    for (const p of held) binding[id + ":" + p] = (binding[id + ":" + p] ?? 0) + (held.length === 1 ? 1 : 0.0001);
    // What the Guide needs to show "until you have N <item> (now M)": the same hold list plus marks.
    const wait = [];
    for (const k of held) wait.push({ item: k, have: inv(k), target: high(k) });
    guideWait[p.id] = wait;
  }
  if (job && job.members && tendCombo(p, id, job)) return;
  if (job && !job.members && job.special !== "noReplaceWhileGrowing") {
    // Leave: products satisfied, layout can't be refilled, or (Uncommons) an earlier farm is ready.
    if (satisfied(id)) {
      if (KNOBS.drainSatisfied && maturing(p, job)) { noteGuide(p, "stay", null, "finishing nearly grown targets"); return; } // nearly grown and still needed: finish them first
      return next(p, "satisfied " + id);
    }
    if (p.layoutShort()) {
      // A full farm that can't be refilled keeps going as a focus variant of its own family
      // (same cells: its inputs and growing targets stay) while that variant is still wanted.
      if (KNOBS.continueFamily && !job.focusOf) for (const v of D.variants[id] ?? []) if (startable(v, p.id)) return enter(p, v, "narrow " + id);
      if (maturing(p, job)) { noteGuide(p, "stay", null, "finishing nearly grown targets, cannot refill"); return; } // let the nearly grown targets finish (no re-placing: it is short)
      return next(p, "short " + id);
    }
    // The other half of a combined farm can start too: build it beside this one (in place, the
    // standing cells are kept and only its own inputs are spent).
    for (const c of combosOn(p.id)) {
      if (!c.members.includes(id)) continue;
      const other = c.members.find((m) => m !== id);
      if (chooseNow(p.id, other) === other && affordable(comboMissing(p, c.members, c))) return enter(p, c.id, "join " + id);
    }
    // Farms with no paid inputs here (Lonelily field, Choconut focus) cost nothing to leave:
    // they yield the plot as soon as an earlier farm is ready.
    const free = keys(costOn(id, p.id) ?? {}).length === 0;
    if (free) {
      const earlier = choose(p.id, job.family);
      if (earlier !== null) return enter(p, earlier, "preempt " + id);
    }
    const hands = KNOBS.handover === "all" || (KNOBS.handover === "uncommons" && D.jobs[job.family].yieldWhenLow);
    if (hands && atLow(id) && !maturing(p, job)) {
      const earlier = choose(p.id, job.family);
      if (earlier !== null) return enter(p, earlier, "handover " + id);
    }
  }
  if (job && job.special === "noReplaceWhileGrowing" && p.count("devourer") === 0) {
    // No Devourer alive: a ring input destroyed by something other than decay (a blast, a teleport)
    // is never refreshed by the step's own exits. Rebuild the ring now, or move on if it can't be.
    const missing = p.layout.plants.some((q) => { const at = p.at(q.row, q.col); return q.origin === "placed" && !(at && at.kind === q.kind && at.row === q.row && at.col === q.col); });
    if (missing) {
      if (p.layoutShort()) return next(p, "short " + id);
      leftBecause["rebuild " + id] = (leftBecause["rebuild " + id] ?? 0) + 1;
      noteGuide(p, "refresh", id, "rebuild " + id, guideWait[p.id]);
      p.restart();
      return;
    }
  }
  // Other exits (Devourer refresh, Aloe goal reached), read from the step.
  const due = p.exitDue();
  if (due === "done") { noteGuide(p, "done", null, "the step's own exit finished the flow"); return; }
  if (due === "hub") return next(p, "left " + id);
  if (due === id) {
    // Refresh (Devourer after a harvest/decay): re-enter; its on-arrival checks send it
    // to the hub when the stock can't rebuild it.
    leftBecause["refresh " + id] = (leftBecause["refresh " + id] ?? 0) + 1;
    noteGuide(p, "refresh", id, "refresh " + id, guideWait[p.id]);
    p.restart();
    if (p.step.id === "hub") next(p, "refresh short");
    return;
  }
  if (due !== null) return enter(p, due, "special " + id);
  // Stay: re-place what is missing only when the stock covers every gap.
  if (!p.layoutShort()) { noteGuide(p, "stay", null, "working " + id, guideWait[p.id]); p.runPhase("maintain"); }
  else noteGuide(p, "stay", null, "working " + id, guideWait[p.id]);
}

function afterSession() {
  if (complete()) return finish();
  tend(plot);
  if (complete()) finish();
}

function onCycleEnd() {
  // A later plot's harvest may finish the goal after this plot's session.
  if (online && complete() && plot.step.id !== "done") finish();
}

function onStart() {
  if (complete()) return finish();
  tend(plot);
}
